def test_search_tasks_return_type():
    # Assuming the test database contains a known task with title 'Example'
    term = 'Example'
    result = db.search_tasks(term)
    assert isinstance(result, list)
    for row in result:
        assert isinstance(row, dict)
        # Expected keys from the tasks table
        for key in ('id', 'title', 'owner_id', 'priority', 'done'):
            assert key in row

def test_percent_zero_denominator():
