    assert percent(0, 0) == 0.0

def test_get_display_name_unknown_user(monkeypatch):
    from app.services import user
    def mock_get_user(user_id):
        return None
    monkeypatch.setattr(user, 'get_user', mock_get_user)
    assert user.get_display_name(123) == "unknown"

def test_handle_bulk_email_update_success(monkeypatch):
    called = {}
    def fake_update_email(user_id, email):
        called['user_id'] = user_id
        called['email'] = email
    monkeypatch.setattr('app.api.update_email', fake_update_email)
    result = handle_bulk_email_update(1, 'test@example.com')
    assert result == {'status': 200, 'data': {'email': 'test@example.com'}}
    assert called == {'user_id': 1, 'email': 'test@example.com'}

def test_handle_bulk_email_update_failure(monkeypatch):
    def fake_update_email(user_id, email):
        raise RuntimeError('boom')
    monkeypatch.setattr('app.api.update_email', fake_update_email)
    result = handle_bulk_email_update(2, 'fail@example.com')
    assert result == {'status': 500, 'error': 'update failed'}
